INSERT INTO promotion_bid_escrow (
    id, auction_window_id, campaign_id, bidder_user_id, authorized_amount, current_hold,
    status, expires_at, created_at, updated_at
) VALUES (
    #{id}, #{auctionWindowId}, #{campaignId}, #{bidderUserId}, #{authorizedAmount}, #{currentHold},
    #{status}, #{expiresAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT id, auction_window_id, campaign_id, bidder_user_id, authorized_amount, current_hold,
       status, expires_at, created_at, updated_at
FROM promotion_bid_escrow
WHERE auction_window_id = #{auctionWindowId}
  AND campaign_id = #{campaignId}
LIMIT 1

mapper.update:
UPDATE promotion_bid_escrow
SET authorized_amount = #{authorizedAmount}, expires_at = #{expiresAt}, updated_at = #{updatedAt}
WHERE auction_window_id = #{auctionWindowId}
  AND campaign_id = #{campaignId}
  AND status = 'ACTIVE'
  AND authorized_amount < #{authorizedAmount}

UPDATE promotion_bid_escrow
SET current_hold = #{currentHold}, updated_at = #{updatedAt}
WHERE auction_window_id = #{auctionWindowId}
  AND campaign_id = #{campaignId}
  AND status = 'ACTIVE'
  AND authorized_amount >= #{currentHold}

UPDATE promotion_bid_escrow
SET status = 'CLOSED', current_hold = 0, updated_at = #{updatedAt}
WHERE auction_window_id = #{auctionWindowId}
  AND status = 'ACTIVE'
